/*
 * rvc_graph_bin.c — Emit RVC v2 ONNX graph from serialized binary data.
 *
 * The binary format is generated by tools/gen_bin.py from a reference ONNX file.
 * This file provides rvc_emit_graph() which reads the binary and emits
 * the complete ONNX graph as NodeProto messages.
 */

#include "rvc_graph.h"
#include "debug.h"
#include <stdlib.h>
#include <string.h>
#include <stdio.h>

/* The binary graph data — generated by tools/gen_bin.py */
#include "graph_data.h"

/* ================================================================== */
/*  Binary reader                                                      */
/* ================================================================== */

typedef struct {
    const uint8_t *p;
    size_t         len;
    size_t         pos;
} BinReader;

static int  br_init(BinReader *r, const uint8_t *data, size_t len)
{
    r->p = data; r->len = len; r->pos = 0;
    return 0;
}

static uint8_t  br_u8(BinReader *r)
{
    if (r->pos + 1 > r->len) { fprintf(stderr, "br: OOB u8\n"); exit(1); }
    return r->p[r->pos++];
}

static uint16_t br_u16(BinReader *r)
{
    if (r->pos + 2 > r->len) { fprintf(stderr, "br: OOB u16\n"); exit(1); }
    uint16_t v; memcpy(&v, r->p + r->pos, 2); r->pos += 2; return v;
}

static uint32_t br_u32(BinReader *r)
{
    if (r->pos + 4 > r->len) { fprintf(stderr, "br: OOB u32\n"); exit(1); }
    uint32_t v; memcpy(&v, r->p + r->pos, 4); r->pos += 4; return v;
}

static int64_t  br_i64(BinReader *r)
{
    if (r->pos + 8 > r->len) { fprintf(stderr, "br: OOB i64\n"); exit(1); }
    int64_t v; memcpy(&v, r->p + r->pos, 8); r->pos += 8; return v;
}

static float    br_f32(BinReader *r)
{
    if (r->pos + 4 > r->len) { fprintf(stderr, "br: OOB f32\n"); exit(1); }
    float v; memcpy(&v, r->p + r->pos, 4); r->pos += 4; return v;
}

static const uint8_t *br_bytes(BinReader *r, size_t n)
{
    if (r->pos + n > r->len) { fprintf(stderr, "br: OOB bytes(%zu)\n", n); exit(1); }
    const uint8_t *p = r->p + r->pos;
    r->pos += n;
    return p;
}

/* ================================================================== */
/*  Node emission from binary                                          */
/* ================================================================== */

/*
 * Emit a single node from binary data into the arena.
 */
static void emit_node_from_bin(BinReader *r, NodeArena *a)
{
    uint8_t type = br_u8(r);
    
    if (type != 'C' && type != 'F' && type != 'V' && type != 'I' &&
        type != 'X' && type != 'G' && type != 'N') {
        fprintf(stderr, "emit_node_from_bin: bad type 0x%02x at pos=%zu/%zu\n",
                type, r->pos, r->len);
        exit(1);
    }
    
    switch (type) {
    case 'C': { /* const_i64 */
        uint32_t name_len = br_u32(r);
        if (name_len > 256) { fprintf(stderr, "C: absurd name_len=%u at pos=%zu\n", name_len, r->pos); exit(1); }
        char *name = (char *)malloc(name_len + 1);
        memcpy(name, br_bytes(r, name_len), name_len);
        name[name_len] = 0;
        int64_t val = br_i64(r);
        emit_const_i64(a, name, val);
        free(name);
        break;
    }
    case 'F': { /* const_f32 */
        uint32_t name_len = br_u32(r);
        if (name_len > 256) { fprintf(stderr, "F: absurd name_len=%u at pos=%zu\n", name_len, r->pos); exit(1); }
        char *name = (char *)malloc(name_len + 1);
        memcpy(name, br_bytes(r, name_len), name_len);
        name[name_len] = 0;
        float val = br_f32(r);
        emit_const_f32(a, name, val);
        free(name);
        break;
    }
    case 'V': { /* const_i64v1 */
        uint32_t name_len = br_u32(r);
        if (name_len > 256) { fprintf(stderr, "V: absurd name_len=%u at pos=%zu\n", name_len, r->pos); exit(1); }
        char *name = (char *)malloc(name_len + 1);
        memcpy(name, br_bytes(r, name_len), name_len);
        name[name_len] = 0;
        int64_t val = br_i64(r);
        emit_const_i64v1(a, name, val);
        free(name);
        break;
    }
    case 'I': { /* const_i64vec */
        uint32_t name_len = br_u32(r);
        if (name_len > 256) { fprintf(stderr, "I: absurd name_len=%u at pos=%zu\n", name_len, r->pos); exit(1); }
        char *name = (char *)malloc(name_len + 1);
        memcpy(name, br_bytes(r, name_len), name_len);
        name[name_len] = 0;
        uint32_t ndims = br_u32(r);
        if (ndims > 8) { fprintf(stderr, "I: absurd ndims=%u at pos=%zu\n", ndims, r->pos); exit(1); }
        int64_t dims[8];
        for (uint32_t i = 0; i < ndims; i++) dims[i] = br_i64(r);
        uint32_t nvals = br_u32(r);
        if (nvals > 64) { fprintf(stderr, "I: absurd nvals=%u at pos=%zu\n", nvals, r->pos); exit(1); }
        int64_t vals[64];
        for (uint32_t i = 0; i < nvals; i++) vals[i] = br_i64(r);
        
        /* Emit as a Constant node with int64 tensor */
        Buf tbuf; buf_init(&tbuf);
        onnx_emit_tensor(&tbuf, NULL, dims, ndims, ONNX_TENSOR_INT64,
                         (const uint8_t *)vals, nvals * 8);
        Buf abuf; buf_init(&abuf);
        pb_string(&abuf, 1, "value");
        pb_message(&abuf, 5, &tbuf);
        pb_uint32(&abuf, 20, ONNX_ATTR_TENSOR);
        
        Buf *b = (Buf *)calloc(1, sizeof(Buf));
        buf_init(b);
        const char *out[] = { name };
        const Buf *attr_ptrs[] = { &abuf };
        onnx_emit_node(b, "Constant", NULL, NULL, 0, out, 1, attr_ptrs, 1);
        buf_free(&tbuf); buf_free(&abuf);
        free(name);
        arena_add(a, b);
        break;
    }
    case 'X': { /* const_f32vec */
        uint32_t name_len = br_u32(r);
        if (name_len > 256) { fprintf(stderr, "X: absurd name_len=%u at pos=%zu\n", name_len, r->pos); exit(1); }
        char *name = (char *)malloc(name_len + 1);
        memcpy(name, br_bytes(r, name_len), name_len);
        name[name_len] = 0;
        uint32_t ndims = br_u32(r);
        if (ndims > 8) { fprintf(stderr, "X: absurd ndims=%u at pos=%zu\n", ndims, r->pos); exit(1); }
        int64_t dims[8];
        for (uint32_t i = 0; i < ndims; i++) dims[i] = br_i64(r);
        uint32_t nvals = br_u32(r);
        if (nvals > 4096) { fprintf(stderr, "X: absurd nvals=%u at pos=%zu\n", nvals, r->pos); exit(1); }
        float *vals = (float *)malloc(nvals * sizeof(float));
        for (uint32_t i = 0; i < nvals; i++) vals[i] = br_f32(r);
        
        Buf tbuf; buf_init(&tbuf);
        onnx_emit_tensor(&tbuf, NULL, dims, ndims, ONNX_TENSOR_FLOAT,
                         (const uint8_t *)vals, nvals * 4);
        free(vals);
        Buf abuf; buf_init(&abuf);
        pb_string(&abuf, 1, "value");
        pb_message(&abuf, 5, &tbuf);
        pb_uint32(&abuf, 20, ONNX_ATTR_TENSOR);
        
        Buf *b = (Buf *)calloc(1, sizeof(Buf));
        buf_init(b);
        const char *out[] = { name };
        const Buf *attr_ptrs[] = { &abuf };
        onnx_emit_node(b, "Constant", NULL, NULL, 0, out, 1, attr_ptrs, 1);
        buf_free(&tbuf); buf_free(&abuf);
        free(name);
        arena_add(a, b);
        break;
    }
    case 'G': { /* const_generic (raw data): [dtype][ndims][dims][data_len][data] */
        uint32_t name_len = br_u32(r);
        if (name_len > 256) { fprintf(stderr, "G: absurd name_len=%u at pos=%zu\n", name_len, r->pos); exit(1); }
        char *name = (char *)malloc(name_len + 1);
        memcpy(name, br_bytes(r, name_len), name_len);
        name[name_len] = 0;
        uint32_t dtype = br_u32(r);
        uint32_t ndims = br_u32(r);
        if (ndims > 8) { fprintf(stderr, "G: absurd ndims=%u at pos=%zu\n", ndims, r->pos); exit(1); }
        int64_t dims[8];
        for (uint32_t i = 0; i < ndims; i++) dims[i] = br_i64(r);
        uint32_t data_len = br_u32(r);
        if (data_len > 10 * 1024 * 1024) { fprintf(stderr, "G: absurd data_len=%u at pos=%zu\n", data_len, r->pos); exit(1); }
        const uint8_t *data = br_bytes(r, data_len);
        
        int onnx_type = (int)dtype;
        if (onnx_type == 0) onnx_type = ONNX_TENSOR_FLOAT;
        
        Buf tbuf; buf_init(&tbuf);
        onnx_emit_tensor(&tbuf, NULL, dims, ndims, onnx_type, data, data_len);
        Buf abuf; buf_init(&abuf);
        pb_string(&abuf, 1, "value");
        pb_message(&abuf, 5, &tbuf);
        pb_uint32(&abuf, 20, ONNX_ATTR_TENSOR);
        
        Buf *b = (Buf *)calloc(1, sizeof(Buf));
        buf_init(b);
        const char *out[] = { name };
        const Buf *attr_ptrs[] = { &abuf };
        onnx_emit_node(b, "Constant", NULL, NULL, 0, out, 1, attr_ptrs, 1);
        buf_free(&tbuf); buf_free(&abuf);
        free(name);
        arena_add(a, b);
        break;
    }
    case 'N': { /* regular node */
        uint32_t op_len = br_u32(r);
        if (op_len > 1024) { fprintf(stderr, "N: absurd op_len=%u at pos=%zu\n", op_len, r->pos); exit(1); }
        /* Copy + null-terminate op type */
        char *op = (char *)malloc(op_len + 1);
        memcpy(op, br_bytes(r, op_len), op_len);
        op[op_len] = 0;
        
        uint16_t n_in = br_u16(r);
        if (n_in > 64) { fprintf(stderr, "N: absurd n_in=%u at pos=%zu\n", n_in, r->pos); exit(1); }
        const char **inputs = NULL;
        if (n_in > 0) {
            inputs = (const char **)malloc(n_in * sizeof(char *));
            for (uint16_t i = 0; i < n_in; i++) {
                uint32_t len = br_u32(r);
                if (len > 4096) { fprintf(stderr, "N: absurd input len=%u at pos=%zu\n", len, r->pos); exit(1); }
                char *s = (char *)malloc(len + 1);
                memcpy(s, br_bytes(r, len), len);
                s[len] = 0;
                inputs[i] = s;
            }
        }
        
        uint16_t n_out = br_u16(r);
        if (n_out > 64) { fprintf(stderr, "N: absurd n_out=%u at pos=%zu\n", n_out, r->pos); exit(1); }
        const char **outputs = NULL;
        if (n_out > 0) {
            outputs = (const char **)malloc(n_out * sizeof(char *));
            for (uint16_t i = 0; i < n_out; i++) {
                uint32_t len = br_u32(r);
                if (len > 4096) { fprintf(stderr, "N: absurd output len=%u at pos=%zu\n", len, r->pos); exit(1); }
                char *s = (char *)malloc(len + 1);
                memcpy(s, br_bytes(r, len), len);
                s[len] = 0;
                outputs[i] = s;
            }
        }
        
        uint16_t n_attr = br_u16(r);
        if (n_attr > 32) { fprintf(stderr, "N: absurd n_attr=%u at pos=%zu\n", n_attr, r->pos); exit(1); }
        Buf *abufs = NULL;
        if (n_attr > 0) {
            abufs = (Buf *)calloc(n_attr, sizeof(Buf));
            for (uint16_t i = 0; i < n_attr; i++) {
                buf_init(&abufs[i]);
                uint32_t name_len = br_u32(r);
                if (name_len > 256) { fprintf(stderr, "N: absurd attr name_len=%u at pos=%zu\n", name_len, r->pos); exit(1); }
                char *attr_name = (char *)malloc(name_len + 1);
                memcpy(attr_name, br_bytes(r, name_len), name_len);
                attr_name[name_len] = 0;
                uint8_t attr_type = br_u8(r);
                uint32_t n_vals = br_u32(r);
                if (n_vals > 1024) { fprintf(stderr, "N: absurd n_vals=%u at pos=%zu\n", n_vals, r->pos); exit(1); }
                
                switch (attr_type) {
                case 0: { /* int */
                    int64_t val = br_i64(r);
                    onnx_emit_attr_int(&abufs[i], attr_name, val);
                    break;
                }
                case 1: { /* float */
                    float val = br_f32(r);
                    br_bytes(r, 4); /* skip padding */
                    onnx_emit_attr_float(&abufs[i], attr_name, val);
                    break;
                }
                case 2: { /* ints */
                    int64_t *vals = (int64_t *)malloc(n_vals * sizeof(int64_t));
                    for (uint32_t j = 0; j < n_vals; j++) vals[j] = br_i64(r);
                    onnx_emit_attr_ints(&abufs[i], attr_name, vals, n_vals);
                    free(vals);
                    break;
                }
                case 5: { /* string: n_vals already read, then [4B len][bytes] */
                    uint32_t s_len = br_u32(r);
                    if (s_len > 256) { fprintf(stderr, "N: string absurd len=%u\n", s_len); exit(1); }
                    char *s_val = (char *)malloc(s_len + 1);
                    memcpy(s_val, br_bytes(r, s_len), s_len);
                    s_val[s_len] = 0;
                    onnx_emit_attr_string(&abufs[i], attr_name, s_val);
                    free(s_val);
                    break;
                }
                case 4: { /* tensor: n_vals, dtype, ndims, dims, data_len, data */
                    uint32_t dtype = br_u32(r);
                    uint32_t ndims = br_u32(r);
                    if (ndims > 8) { fprintf(stderr, "N: tensor absurd ndims=%u\n", ndims); exit(1); }
                    int64_t dims[8];
                    for (uint32_t j = 0; j < ndims; j++) dims[j] = br_i64(r);
                    uint32_t data_len = br_u32(r);
                    if (data_len > 10 * 1024 * 1024) { fprintf(stderr, "N: tensor absurd data_len=%u\n", data_len); exit(1); }
                    const uint8_t *tdata = br_bytes(r, data_len);
                    Buf tbuf; buf_init(&tbuf);
                    onnx_emit_tensor(&tbuf, NULL, dims, ndims, (int)dtype,
                                     tdata, data_len);
                    pb_string(&abufs[i], 1, attr_name);
                    pb_message(&abufs[i], 5, &tbuf);
                    pb_uint32(&abufs[i], 20, ONNX_ATTR_TENSOR);
                    buf_free(&tbuf);
                    break;
                }
                default:
                    /* Skip unknown attr type */
                    br_bytes(r, n_vals * 8);
                    break;
                }
                free(attr_name);
            }
        }
        
        Buf *b = (Buf *)calloc(1, sizeof(Buf));
        buf_init(b);
        const Buf **attr_ptrs = NULL;
        if (n_attr > 0) {
            attr_ptrs = (const Buf **)malloc(n_attr * sizeof(Buf *));
            for (uint16_t i = 0; i < n_attr; i++) attr_ptrs[i] = &abufs[i];
        }
        onnx_emit_node(b, op, NULL, inputs, n_in, outputs, n_out,
                       attr_ptrs, n_attr);
        free(attr_ptrs);
        free(op);
        if (inputs) { for (uint16_t i = 0; i < n_in; i++) free((void *)inputs[i]); free(inputs); }
        if (outputs) { for (uint16_t i = 0; i < n_out; i++) free((void *)outputs[i]); free(outputs); }
        if (abufs) {
            for (uint16_t i = 0; i < n_attr; i++) buf_free(&abufs[i]);
            free(abufs);
        }
        arena_add(a, b);
        break;
    }
    default:
        fprintf(stderr, "emit_node_from_bin: unknown type '%c' (0x%02x)\n", type, type);
        exit(1);
    }
}

/* ================================================================== */
/*  Public API                                                         */
/* ================================================================== */

int rvc_emit_graph(const RvcParams *p,
                   const RvcWeight *weights, size_t n_weights,
                   Buf ***nodes_out, size_t *n_nodes_out)
{
    (void)p; (void)weights; (void)n_weights;
    
    SPCV_TRACE("graph", "rvc_emit_graph: graph_data_len=%zu", graph_data_len);
    
    BinReader r;
    br_init(&r, graph_data, graph_data_len);
    
    uint32_t n_nodes = br_u32(&r);
    SPCV_TRACE("graph", "n_nodes from binary: %u", n_nodes);
    
    NodeArena a;
    arena_init(&a);
    
    for (uint32_t i = 0; i < n_nodes; i++) {
        if (i % 1000 == 0)
            SPCV_TRACE("graph", "emitting node %u/%u", i, n_nodes);
        emit_node_from_bin(&r, &a);
    }
    
    SPCV_TRACE("graph", "emitted %zu nodes total", a.n);
    *nodes_out = a.items;
    *n_nodes_out = a.n;
    return 0;
}
